options(encoding = "UTF-8")
find_root <- function(path) { current <- normalizePath(path, winslash = "/", mustWork = TRUE); repeat { if (file.exists(file.path(current, ".codex", "study-mmrm-analysis", "R", "intake_enrichment.R"))) return(current); parent <- dirname(current); if (parent == current) stop("project root not found"); current <- parent } }
project_dir <- find_root(getwd()); helper_dir <- file.path(project_dir, ".codex", "study-mmrm-analysis", "R")
for (helper in c("canonical_hash.R", "standard_analysis_definition.R", "analysis_plan.R", "io.R", "specification.R", "intake_extraction.R", "intake_review.R", "runtime_dataset_binding.R", "intake_enrichment.R")) source(file.path(helper_dir, helper), encoding = "UTF-8")
evidence <- data.frame(relative_path = "input/adam-spec.xlsx", sheet = c("ADQSSUM", "ADQSSUM", "QSSUMPARAM", "ADSL"), row = c(1L, 2L, 1L, 1L), text = c("Dataset", "CHG BASE AVISITN", "PARAMCD", "USUBJID"), stringsAsFactors = FALSE)
first <- runtime_dataset_spec_list_datasets(evidence); second <- runtime_dataset_spec_list_datasets(evidence); names1 <- vapply(first$candidates, `[[`, character(1), "name"); stopifnot(identical(first, second), identical(names1, c("ADQSSUM", "ADSL")), all(vapply(first$candidates, function(x) nzchar(x$sheet_ref), logical(1))))
tmp <- tempfile("zz_intake_enrichment_", tmpdir = file.path(project_dir, "studies")); dir.create(file.path(tmp, "input"), recursive = TRUE); dir.create(file.path(tmp, "backup-trace"), recursive = TRUE); dir.create(file.path(tmp, "statistician-review"), recursive = TRUE); on.exit(unlink(tmp, recursive = TRUE, force = TRUE), add = TRUE)
shell <- file.path(tmp, "input", "shell.txt"); writeLines(c("\u886814.2.2 Synthetic MMRM Summary", "MMRM\u7ed3\u679c"), shell, useBytes = TRUE); intake <- write_intake_statistical_review(tmp, project_dir, "ai_source_extraction")
original_evidence <- runtime_dataset_spec_evidence; runtime_dataset_spec_evidence <- function(study_dir, project_dir) evidence; on.exit(assign("runtime_dataset_spec_evidence", original_evidence, envir = globalenv()), add = TRUE)
result <- intake_enrich_review_with_adam(tmp, project_dir, intake$review_path); stopifnot(result$enriched, result$dataset_count == 2L)
lines <- readLines(intake$review_path, encoding = "UTF-8", warn = FALSE); row <- grep("^\\|\\s*\u5206\u6790\u6570\u636e\u96c6\\s*\\|", lines, value = TRUE)[[1L]]; stopifnot(grepl("ADQSSUM", row, fixed = TRUE), grepl("ADSL", row, fixed = TRUE), grepl("ADaM specification sheet=", row, fixed = TRUE), !grepl("sha256=|format=|relative_path=", row))
review <- read_statistical_review(intake$review_path); stopifnot(identical(as.character(review$metadata$review_status), "pending")); pending_plan <- yaml::read_yaml(intake$analysis_plan_path, eval.expr = FALSE); stopifnot(is.null(pending_plan$analyses[[1]]$dataset$file), is.null(pending_plan$analyses[[1]]$mappings$response))
unlink(tmp, recursive = TRUE, force = TRUE); stopifnot(!dir.exists(tmp)); cat("Intake enrichment evidence-only focused check passed.\n")
